Method.Source:
    /// <summary>
    /// Form datasource Active method to enable/disable Shrink wrap field based Modeule category - header/Line auto charges
    /// </summary>
    int active()
    {
        FormCheckBoxControl shrinkWrapControl;
        int ret = next active();

        shrinkWrapControl = this.formRun().design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoTable_METShrinkWrap)) as FormCheckBoxControl;
        MarkupAutoTable markupAutoTable = this.formRun().dataSource().cursor();
        //If the current record is HEader auto charges, then, Shrink wrap field is visible
        if(markupAutoTable.moduleCategory == HeadingLine::Heading)
        {
            shrinkWrapControl.visible(true);
        }
        else
        {
            shrinkWrapControl.visible(false);
        }
        return ret;
    }
